package com.bocsoft.sqleditor.execution;
import com.bocsoft.sqleditor.execution.api.BinaryValue;import java.io.InputStream;import java.math.BigDecimal;import java.sql.*;import java.time.temporal.TemporalAccessor;import org.springframework.stereotype.Component;
@Component public class JdbcValueEncoder {public Object encode(ResultSet rs,int column,int jdbcType)throws SQLException{Object value=rs.getObject(column);if(value==null)return null;switch(jdbcType){case Types.BIGINT:return String.valueOf(value);case Types.DECIMAL:case Types.NUMERIC:return value instanceof BigDecimal?((BigDecimal)value).toPlainString():String.valueOf(value);case Types.BINARY:case Types.VARBINARY:case Types.LONGVARBINARY:case Types.BLOB:byte[]bytes=rs.getBytes(column);return new BinaryValue(bytes==null?0:bytes.length);case Types.DATE:case Types.TIME:case Types.TIME_WITH_TIMEZONE:case Types.TIMESTAMP:case Types.TIMESTAMP_WITH_TIMEZONE:return String.valueOf(value);case Types.TINYINT:case Types.SMALLINT:case Types.INTEGER:return ((Number)value).intValue();case Types.FLOAT:case Types.REAL:case Types.DOUBLE:return ((Number)value).doubleValue();case Types.BOOLEAN:case Types.BIT:return value instanceof Boolean?value:rs.getBoolean(column);default:return value instanceof byte[]?new BinaryValue(((byte[])value).length):String.class.isInstance(value)||Number.class.isInstance(value)||Boolean.class.isInstance(value)?value:String.valueOf(value);}}}
